L('function drawScorpion(c,f,legPhase,stingAngle){const O=1,BD=2,BM=3,BL=4,BH=5,PD=6,PM=7,PL=8,SD=9,SM=10,EY=11,SK=12;const cx=20;c.ellipse(cx,30,8,5,BM);c.ellipse(cx-1,29,7,4,BL);c.ellipse(cx-2,28,6,4,BM);c.ellipse(cx,36,13,7,BM);c.ellipse(cx,24,10,6,BM);c.ellipse(cx,19,8,5,BM);c.ellipse(cx-1,18,5,4,BL);c.set(cx-2,13,BH);c.ellipse(cx+3,32,5,3,BD);c.dither(cx-4,28,5,4,BM,BL);c.dither(cx+2,25,4,3,BM,BD);c.ellipse(cx,11,5,3,BM);c.ellipse(cx-1,10,4,2,BL);c.set(cx-4,10,BH);c.set(cx-4,11,EY);c.set(cx+3,11,EY);c.ellipse(cx-8,12,4,3,PM);c.ellipse(cx-9,11,3,2,PL);c.set(cx-17,11,PD);c.ellipse(cx+8,12,4,3,PM);c.ellipse(cx+9,11,3,2,PL);c.set(cx+17,11,PD);for(let i=0;i<4;i++){const lo=Math.round(Math.sin(legPhase+i*0.6)*1);const lx=cx-10+i*5;c.line(lx,33,lx-3,40+lo,BM);c.set(lx-3,40+lo,BD)}if(stingAngle===0){c.line(cx,10,cx,4,SM);c.line(cx,4,cx+3,1,SM);c.set(cx+3,0,SK);c.set(cx+4,0,SD)}else if(stingAngle===1){c.line(cx,10,cx-3,4,SM);c.line(cx-3,4,cx-6,1,SM);c.set(cx-6,0,SK);c.set(cx-7,0,SD)}else{c.line(cx,10,cx,5,SM);c.line(cx,5,cx,1,SM);c.set(cx,0,SK);c.set(cx-1,0,SD)}c.outline(O)}')
L('function createScorpionSprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawScorpion(c,i,0,0);idle.push(c.toFrame())}const walk=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawScorpion(c,i,i*Math.PI/2,0);walk.push(c.toFrame())}const attack=[];const sa=[0,1,2,0];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawScorpion(c,i,0,sa[i]);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(40,56);drawScorpion(c1,0,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],8))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawScorpion(c,0,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(40,56);for(let y=0;y<56;y++)for(let x=0;x<40;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"scorpion",palette:SCP,animations:{idle:makeAnim("idle",idle,250,true),walk:makeAnim("walk",walk,120,true),attack:makeAnim("attack",attack,120,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

L('function drawMummy(c,f,walkOff,armRaise){const O=1,BD=2,BM=3,BL=4,BH=5,DD=6,DM=7,DL=8,EY=9,EGL=10,BG=11,BGD=12;const by=4+walkOff,cx=20;c.rect(cx-6,14+by,12,18,BM);c.rect(cx-5,14+by,10,16,BL);c.rect(cx-4,14+by,6,13,BH);for(let y=14+by;y<30+by;y+=2)c.line(cx-6,y,cx+5,y,BD);c.line(cx-4,14+by,cx-4,28+by,DL);c.line(cx+3,15+by,cx+3,28+by,BD);c.dither(cx-5,22+by,10,8,BM,DD);c.dither(cx-4,16+by,8,5,BL,DM);c.ellipse(cx,10+by,5,5,BM);c.ellipse(cx-1,9+by,4,4,BL);c.ellipse(cx+1,11+by,3,3,BD);c.line(cx-4,9+by,cx+4,9+by,BD);c.line(cx-3,11+by,cx+3,11+by,BD);c.set(cx-3,8+by,DL);c.set(cx+2,8+by,BD);c.set(cx-2,10+by,EGL);c.set(cx-1,10+by,EY);c.set(cx+1,10+by,EGL);c.set(cx+2,10+by,EY);if(armRaise===0){c.rect(cx-10,16+by,4,11,BM);c.rect(cx+6,16+by,4,11,BM);c.set(cx-10,16+by,BL);c.set(cx+6,16+by,BL);c.dither(cx-10,18+by,4,6,BM,BD);c.dither(cx+6,18+by,4,6,BM,BD)}else{c.rect(cx-10,8+by,4,11,BM);c.rect(cx+6,8+by,4,11,BM);c.set(cx-10,8+by,BL);c.set(cx+9,7+by,BH)}c.rect(cx-4,31+by,4,5,BM);c.rect(cx,31+by,4,5,BM);c.set(cx-4,31+by,BL);c.set(cx,31+by,BL);c.dither(cx-4,32+by,4,3,BM,BD);c.dither(cx,32+by,4,3,BM,BD);c.rect(cx-5,35+by,5,3,BGD);c.rect(cx,35+by,5,3,BGD);c.set(cx-5,35+by,BG);c.set(cx,35+by,BG);c.outline(O)}')
L('function createMummySprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawMummy(c,i,0,0);idle.push(c.toFrame())}const walk=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawMummy(c,i,i%2===0?0:-1,0);walk.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawMummy(c,i,0,i===1?1:0);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(40,56);drawMummy(c1,0,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],10))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawMummy(c,0,0,0);const sf=shiftFrame(c.toFrame(),0,i*3);const c2=new PixelCanvas(40,56);for(let y=0;y<56;y++)for(let x=0;x<40;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"mummy",palette:MP,animations:{idle:makeAnim("idle",idle,250,true),walk:makeAnim("walk",walk,180,true),attack:makeAnim("attack",attack,120,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

L('function drawIceElemental(c,f,pulse){const O=1,ID=2,IM=3,IL=4,IH=5,WH=6,GL=7,GLH=8,SP=9,SPH=10;const by=6,pr=pulse,cx=20;c.ellipse(cx,28+by,10+pr,11+pr,IM);c.ellipse(cx-1,27+by,8+pr,9+pr,IL);c.ellipse(cx-2,26+by,6+pr,6+pr,IH);c.ellipse(cx+2,30+by,7+pr,7+pr,ID);c.set(cx-8,18+by,IL);c.set(cx-9,17+by,IH);c.set(cx+8,18+by,IL);c.set(cx+9,17+by,ID);c.set(cx-4,14+by,IH);c.set(cx-5,13+by,WH);c.set(cx+4,14+by,IL);c.set(cx+5,13+by,ID);c.line(cx-6,20+by,cx,14+by,IL);c.line(cx,14+by,cx+6,20+by,IL);c.line(cx+6,20+by,cx,32+by,ID);c.line(cx-6,20+by,cx,32+by,ID);c.ellipse(cx,28+by,4,4,GL);c.ellipse(cx,28+by,2,2,GLH);c.set(cx,26+by,WH);c.set(cx-5+f,24+by,SP);c.set(cx+6-f,23+by,SPH);c.set(cx-2,34+by-f,SP);c.set(cx+3,35+by-f,SPH);c.dither(cx-6,24+by,5,5,IM,IL);c.dither(cx+2,26+by,5,5,IM,ID);c.set(cx-4,26+by,15);c.set(cx+4,26+by,15);c.outline(O)}')
L('function createIceElementalSprite(){const idle=[];const pu=[0,1.5,-1.5,0];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawIceElemental(c,i,pu[i]);idle.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawIceElemental(c,i,i+1);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(40,56);drawIceElemental(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],9))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawIceElemental(c,0,-i);death.push(c.toFrame())}return{id:"ice_elemental",palette:IP,animations:{idle:makeAnim("idle",idle,250,true),attack:makeAnim("attack",attack,120,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

