L('function drawFallenSaint(c,f,at){const O=1,BD=2,BM=3,BL=4,BH=5,AD=6,AM=7,AH=8,AL=9,BCA=10,BCB=11,BCC=12,BCC2=13,WH=14,CL=15,HALO=16,HV=17,MW=18;const cx=36,by=4+at;c.ellipse(cx,26+by,10,14,BCA);c.ellipse(cx-1,25+by,8,12,BCB);c.ellipse(cx+2,27+by,7,11,AD);c.line(cx-6,16+by,cx-7,38+by,AD);c.line(cx+6,16+by,cx+7,38+by,AD);c.set(cx-5,22+by,BCB);c.set(cx+5,25+by,AD);c.rect(cx-8,17+by,16,11,AM);c.rect(cx-7,17+by,14,3,AH);c.rect(cx-8,26+by,16,2,BD);c.rect(cx+4,18+by,5,8,BD);c.rect(cx-7,18+by,4,7,AL);c.line(cx-5,18+by,cx-5,26+by,BD);c.set(cx-4,19+by,AH);c.set(cx-3,19+by,AH);c.set(cx-4,23+by,AM);c.ellipse(cx,11+by,5,5,AM);c.ellipse(cx-1,10+by,4,4,AH);c.ellipse(cx+1,12+by,3,3,BD);c.ellipse(cx,8+by,6,4,AM);c.ellipse(cx-1,7+by,4,3,AH);c.set(cx-5,7+by,HALO);c.set(cx-4,6+by,HV);c.set(cx+4,7+by,HV);c.set(cx-2,5+by,CL);c.set(cx+2,5+by,CL);c.set(cx-2,11+by,WH);c.set(cx+2,11+by,WH);c.ellipse(cx-9,17+by,4,3,AM);c.ellipse(cx+9,17+by,4,3,AM);c.set(cx-11,16+by,AH);c.set(cx+11,16+by,AH);c.ellipse(cx-12,8+by,5,4,HALO);c.ellipse(cx-13,7+by,4,3,HV);c.ellipse(cx+12,8+by,5,4,HALO);c.ellipse(cx+13,7+by,4,3,HV);c.set(cx-14,6+by,CL);c.set(cx+14,6+by,CL);c.set(cx-13,4+by,HV);c.set(cx+13,4+by,HV);const llX=cx-4,lrX=cx+2,llO=Math.round(Math.sin(f)*2),lrO=Math.round(Math.sin(f+Math.PI)*2);c.rect(llX,30+by,4,5+llO,AM);c.rect(lrX,30+by,4,5+lrO,AM);c.set(llX,30+by,AL);c.set(lrX,30+by,AL);c.rect(llX-1,34+by+llO,5,4,BD);c.rect(lrX-1,34+by+lrO,5,4,BD);c.set(llX-1,34+by+llO,AM);c.set(lrX-1,34+by+lrO,AM);c.set(llX,34+by+llO,AL);c.set(lrX,34+by+lrO,AL);c.set(cx+10,12+by,MW);c.set(cx+11,12+by,MW);if(at>=2){c.rect(cx+12,10+by,2,8,MW);c.set(cx+12,10+by,WH)}c.outline(O)}')
L('function createFallenSaintSprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawFallenSaint(c,i,0);idle.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawFallenSaint(c,i,i);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(72,96);drawFallenSaint(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],18))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawFallenSaint(c,0,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(72,96);for(let y=0;y<96;y++)for(let x=0;x<72;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"fallen_spirit",palette:FSP,animations:{idle:makeAnim("idle",idle,200,true),attack:makeAnim("attack",attack,100,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

